 // Display the saved object pool after deadline reduction, before worker allocation.
 private static function distributionPool(array $object): ?int {
  $gross=$object['grossCents']??null;$deadline=$object['deadlineCents']??null;
  return $gross===null||$deadline===null?null:(int)$gross-(int)$deadline;
 }
 // Original contribution belongs to the saved object slice, before payout decisions.
 private static function weightTotals(array $recipients): array {
  $totals=[];$unknown=[];
  foreach($recipients as $recipient){
   $id=(string)$recipient['objectId'];$weight=$recipient['originalWeight']??$recipient['weight']??null;
   if(!is_numeric($weight)||$weight<0){$unknown[$id]=true;continue;}
   $totals[$id]=($totals[$id]??0)+(int)$weight;
  }
  foreach($unknown as $id=>$_)$totals[$id]=null;
  return $totals;
 }
 private static function contribution(array $recipient,array $totals): array {
  $total=$totals[(string)$recipient['objectId']]??0;
  return ['value'=>$total>0?(int)($recipient['originalWeight']??$recipient['weight'])/$total:'','style'=>3];
 }
 private static function employment(?string $value): string {
